    LANGUAGE_WRAPPER = 'In a math contest, the angle parameter {a} is a positive integer. Let {k} positive reals x_1, x_2, ..., x_{k} be given, together with an integer exponent {r} ≥ 3 and a list of integers α_1, α_2, ..., α_{k-1} specified as [alpha_values], where each α_i satisfies 1 ≤ α_i ≤ {r}−1. Define β_i = {r} − α_i for i = 1, 2, ..., {k}−1. Determine the exact maximum value of the quantity:\n\n((16 (cos {a})^5 − cos(5 {a})) / (2 cos {a} + cos(3 {a}))) × (Σ_{i=1}^{k−1} x_i^{α_i} x_{i+1}^{β_i}) / (Σ_{i=1}^{k} x_i^{r}).\n\nReport your answer in the form:\n### The final answer is: \\boxed{<your answer>}'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
import math
# Randomly select parameters under constraints; retry until nontrivial and valid
for _ in range(200):
    k = rng.randint(4, 7)
    r = rng.randint(3, 9)
    # Choose alphas with diversity
    alphas = [rng.randint(1, r-1) for _ in range(k-1)]
    # Ensure at least two distinct alphas for nontriviality
    if len(set(alphas)) < 2:
        continue
    # Compute coefficients c_j from weighted AM-GM bound
    # c_1 = α_1; c_j = (r - α_{j-1}) + α_j for 2<=j<=k-1; c_k = r - α_{k-1}
    coeffs = []
    coeffs.append(alphas[0])
    for j in range(1, k-1):
        coeffs.append((r - alphas[j-1]) + alphas[j])
    coeffs.append(r - alphas[-1])
    M = max(coeffs)
    # Avoid trivial max = r (which would make the ratio attain 1 too easily)
    if M >= r:
        continue
    # Also avoid too small maximum to keep difficulty; enforce M >= ceil(r/2)+1
    lower_bound = (r + 1)//2 + 1
    if M < lower_bound:
        continue
    # Choose a positive integer a such that denominator is not too small
    a = rng.randint(1, 500)
    d = 2*math.cos(a) + math.cos(3*a)
    if abs(d) < 1e-10:
        continue
    # Successful instance
    alpha_values = ", ".join(str(x) for x in alphas)
    return {
        'a': a,
        'k': k,
        'r': r,
        'alphas': alphas,
        'alpha_values': alpha_values
    }
# Fallback deterministic instance if random generation fails
k = 5
r = 6
alphas = [2, 4, 3, 1]
alpha_values = ", ".join(str(x) for x in alphas)
return {
    'a': 7,
    'k': k,
    'r': r,
    'alphas': alphas,
    'alpha_values': alpha_values
}

